Object.assign(labels,{proveedores:'Proveedores',cierres:'Historial de caja',radar:'Radar de stock',tendencia:'Tendencia por producto',periodos:'Comparativa mensual',balance:'Balance general',margen:'Margen real',finanzas:'Finanzas',general:'Reporte general',ranking:'Ventas por producto',ajustes:'Ajustes de inventario'});
Object.assign(reportKinds,{mensual:'Histórico mensual de resultados',compras_dashboard:'Análisis de compras',flujo:'Flujo de fondos',cartera_aging:'Antigüedad de cartera',proveedores_aging:'Antigüedad de proveedores',categorias:'Valoración por categoría',servicios:'Servicios y taller',ajustes_stock:'Ajustes de inventario'});
