const auditState={filters:{},statement:null,includeArchived:false};
const auditReportAccess={ventas:'ventas',general:'general',finanzas:'finanzas',productos:'ranking',periodos:'periodos',mensual:'periodos',balance:'balance',margen:'margen',tendencia:'tendencia',radar:'radar',compras:'compras',compras_dashboard:'reportescompras',libro_compras:'reportescompras',cartera:'cartera',cartera_aging:'cartera',creditos_proveedores:'creditos',proveedores_aging:'creditos',abonos_ventas:'abonos',abonos_compras:'abonoscompras',cierres:'cierres',flujo:'caja',inventario:'inventario',ajustes_stock:'inventario',servicios:'servicios',categorias:'categorias'};
function auditFilters(){return auditState.filters[appState.route]||{};}
function auditRange(preset){const day=appState.today,at=new Date(day+'T12:00:00Z'),iso=d=>d.toISOString().slice(0,10),shift=n=>new Date(at.getTime()+n*86400000),weekday=(at.getUTCDay()+6)%7;
 switch(preset){case'today':return {start:day,end:day};case'yesterday':return {start:iso(shift(-1)),end:iso(shift(-1))};case'7d':return {start:iso(shift(-6)),end:day};case'week':return {start:iso(shift(-weekday)),end:day};case'lastweek':return {start:iso(shift(-weekday-7)),end:iso(shift(-weekday-1))};case'lastmonth':return {start:iso(new Date(Date.UTC(at.getUTCFullYear(),at.getUTCMonth()-1,1))),end:iso(new Date(Date.UTC(at.getUTCFullYear(),at.getUTCMonth(),0)))};case'year':return {start:day.slice(0,4)+'-01-01',end:day};case'month':return {start:day.slice(0,7)+'-01',end:day};case'30d':return {start:iso(shift(-29)),end:day};default:return {start:'0001-01-01',end:day};}}
function auditPeriodButtons(prefix='audit-period-'){return `<div class="row audit-periods">${[['Hoy','today'],['Ayer','yesterday'],['Últimos 7 días','7d'],['Esta semana','week'],['Semana pasada','lastweek'],['Este mes','month'],['Mes pasado','lastmonth'],['Este año','year'],['Últimos 30 días','30d'],['Histórico','all']].map(([label,id])=>pButton(label,prefix+id,'text')).join('')}</div>`;}
function auditListControls(kind){const f=auditFilters();return `<section class="card audit-controls"><div class="card-body"><div class="row">${input('Desde','audit-start',f.start||'0001-01-01','date')+input('Hasta','audit-end',f.end||appState.today,'date')+select('Estado','audit-status',[['','Todos'],['paid','Pagadas'],['pending','Pendientes'],['void','Anuladas'],...(kind==='ventas'?[['layaway','Separes']]:[])],f.status||'')+select('Medio','audit-method',[['','Todos'],['cash','Efectivo'],['transfer','Transferencia'],['card','Tarjeta']],f.method||'')}${pButton('Aplicar filtros','audit-list-apply','primary')}${pButton('Limpiar','audit-list-clear')}</div>${auditPeriodButtons('audit-list-period-')}</div></section>`;}
function auditDate(v){return v?.length===10?v:new Date(v).toLocaleDateString('en-CA',{timeZone:'America/Bogota'});}
function auditMatches(o){const f=auditFilters(),date=o.date||auditDate(o.createdAt),state=o.voidedAt?'void':balance(o)>0?'pending':'paid';return (!f.start||date>=f.start)&&(!f.end||date<=f.end)&&(!f.status||f.status===state||f.status==='layaway'&&o.mode==='layaway')&&(!f.method||o.payments?.some(p=>!p.voidedAt&&p.method===f.method));}
const auditedSalesTable=salesTable;
salesView=function(){const list=filtered(data().sales.filter(auditMatches),s=>[s.id,s.customer,s.customerDoc,s.cashier,s.date,...s.items.map(i=>i.name)].join(' '));return heading('Cada venta tiene una historia.','Filtra el historial; la exportación conserva el mismo periodo, estado y búsqueda.',allowed('pos','crear')?button('Nueva venta','goto-pos','primary','plus'):'')+auditListControls('ventas')+`<section class="card">${search('Buscar venta, cliente, pieza o vendedor',exportButtons('ventas'))}<div id="results">${auditedSalesTable(list)}</div></section>`;};
const auditedPurchaseRows=purchaseRows;
purchaseRows=function(){if(appState.tab==='proveedores')return auditedPurchaseRows();const s=data(),visible=s.purchases.filter(o=>auditMatches(o)&&(appState.tab!=='pendientes'||balance(o)>0));appState.data={...s,purchases:visible};try{return auditedPurchaseRows();}finally{appState.data=s;}};
const auditedPurchasesView=purchasesView;
