const oldExport=downloadExport;
downloadExport=async function(module,format){if(!['ventas','compras'].includes(module))return oldExport(module,format);const f={...auditFilters(),query:appState.query||'',module},payload=await api('/api/export?'+new URLSearchParams(f));return auditDownloadSheets({title:module,sheets:[{name:module,headers:payload.headers,rows:payload.rows}]},format);};
function auditDownloadSheets(book,format='xls'){const safe=v=>typeof v==='string'&&/^[=+\-@\t\r]/.test(v)?"'"+v:v,xml=v=>esc(safe(v)).replace(/&#39;/g,'&apos;');let content,type;
 if(format==='csv'){const rows=[book.sheets[0].headers,...book.sheets[0].rows];content='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(safe(v)).replaceAll('"','""')+'"').join(';')).join('\r\n');type='text/csv;charset=utf-8';}
 else{content='<?xml version="1.0"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">'+book.sheets.map(sheet=>'<Worksheet ss:Name="'+xml(sheet.name.slice(0,31))+'"><Table>'+[sheet.headers,...sheet.rows].map(row=>'<Row>'+row.map(v=>'<Cell><Data ss:Type="'+(typeof v==='number'?'Number':'String')+'">'+xml(v??'')+'</Data></Cell>').join('')+'</Row>').join('')+'</Table></Worksheet>').join('')+'</Workbook>';type='application/vnd.ms-excel';}
 executiveDownload(new Blob([content],{type}),'Aurea-'+book.title.replace(/[^\p{L}\p{N}-]+/gu,'-')+'-'+appState.today+'.'+format);
}
async function auditWorkbook(book,extra={}){if(book==='turno')extra={shiftId:activeShift()?.id,...extra};const result=await api('/api/workbook?'+new URLSearchParams({book,start:appState.start,end:appState.end,...parityState.filters,...extra}));auditDownloadSheets(result);}
function auditChart(chart){const points=chart.points||[];if(!points.length)return '';if(points.length<=12)return executiveBars(chart.title,points.map(([name,value])=>({name,value})));const width=680,height=180,values=points.map(p=>p[1]),min=Math.min(0,...values),max=Math.max(1,...values),y=v=>150-(v-min)/(max-min)*130,x=i=>20+i/(points.length-1)*640,path=points.map((p,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(p[1]).toFixed(1)).join(' ');return `<section class="card"><div class="card-head"><h2>${esc(chart.title)}</h2></div><div class="card-body"><svg class="audit-line" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(chart.title+': '+points.map(p=>p.join(' ')).join('; '))}"><path d="M20 ${y(0)}H660" stroke="var(--border)"/><path d="${path}" fill="none" stroke="var(--green)" stroke-width="3"/>${[0,Math.floor(points.length/2),points.length-1].map(i=>`<text x="${x(i)}" y="175" text-anchor="${i===0?'start':i===points.length-1?'end':'middle'}" fill="currentColor" font-size="11">${esc(points[i][0])}</text>`).join('')}</svg></div></section>`;}
loadDetailedReport=async function(){const target=document.querySelector('#parity-report');if(!target)return;const kind=parityState.kind;try{const p=await api('/api/analytics?'+filterQuery());if(!target.isConnected||kind!==parityState.kind)return;parityState.payload=p;let cards='';const s=p.summary;if(s){if(['general','finanzas','margen'].includes(kind))cards=kpi('Ventas netas',money(s.netSales))+kpi('Costo histórico',money(s.cost))+kpi('Utilidad bruta',money(s.grossProfit))+kpi('Resultado operativo',money(s.operatingProfit),'Después de gastos',true);else if(['compras','compras_dashboard'].includes(kind))cards=kpi('Compras',money(s.total))+kpi('Pagado',money(s.paid))+kpi('Pendiente',money(s.pending))+kpi('Órdenes',s.orders);else if(['cartera','cartera_aging','creditos_proveedores','proveedores_aging'].includes(kind))cards=kpi('Saldo pendiente',money(s.balance))+kpi('Saldo vencido',money(s.overdue));else if(kind==='radar')cards=kpi('Críticos',s.critical)+kpi('Alertas',s.alert)+kpi('Agotados',s.out)+kpi('Sin movimiento',s.noMovement);else if(kind==='tendencia')cards=kpi(s.product,Number(s.qty).toLocaleString('es-CO')+' '+(s.measureType==='Pesaje'?'g':'un.'))+kpi('Ingresos del periodo',money(s.revenue))+kpi('Stock actual',countLabel({measureType:s.measureType},s.stock));else if(kind==='balance')cards=kpi('Activos',money(s.assets))+kpi('Pasivos',money(s.liabilities))+kpi('Patrimonio',money(s.equity));else if(kind==='flujo')cards=kpi('Entradas',money(s.income))+kpi('Salidas',money(s.outcome))+kpi('Flujo neto registrado',money(s.net));}
 target.innerHTML=(cards?'<div class="kpis audit-kpis">'+cards+'</div>':'')+payloadTable(p)+(p.charts?.length?'<div class="grid-equal audit-charts">'+p.charts.map(auditChart).join('')+'</div>':'');
 }catch(e){if(target.isConnected)target.innerHTML=empty('No pudimos generar el informe',e.message,pButton('Reintentar','report-retry','primary'));}};
const auditedReportFilters=reportFilters;
reportFilters=function(){const template=document.createElement('template');template.innerHTML=auditedReportFilters();template.content.querySelectorAll('[name=parity-kind] option').forEach(o=>{if(!allowed(auditReportAccess[o.value]||'reportes')||!isSuper()&&privateReports.includes(o.value))o.remove();});template.content.querySelectorAll('[data-action="x-period-today"],[data-action="x-period-week"],[data-action="x-period-month"],[data-action="x-period-all"]').forEach(el=>el.remove());const holder=template.content.querySelector('.report-selects');if(holder)holder.insertAdjacentHTML('beforeend',input('Buscar en el informe','parity-query',parityState.filters.query||'','search'));return template.innerHTML+auditPeriodButtons();};
