async function auditStatement(kind,id){const r=await api('/api/statement?'+new URLSearchParams({kind,id}));auditState.statement=r;const supplier=kind==='supplier',module=supplier?'proveedores':'clientes',c=r.contact;modal('Estado de cuenta · '+c.name,`<p>${esc(c.doc)} · ${esc(c.phone||'Sin teléfono')} · ${esc(c.email||'')}</p><p>${esc(c.address||'')}</p>${supplier?'<p>Banco: '+esc(c.bank||'Sin registrar')+' · '+esc(c.accountType||'')+' · '+esc(c.accountNumber||'')+'</p>':''}<div class="kpis">${kpi('Total registrado',money(r.granted))+kpi('Abonado',money(r.paid))+kpi('Saldo',money(r.balance))+kpi('Vencido',money(r.overdue))}</div><h3>Operaciones vinculadas</h3>${table(['Operación','Fecha','Total COP','Saldo COP','Estado',''],r.orders.map(o=>`<tr><td>${esc(o.id)}<small>${esc(o.invoice||o.mode||'')}</small></td><td>${fmtDate(o.createdAt)}</td><td class="num">${money(o.total)}</td><td class="num">${money(balance(o))}</td><td>${badge(o.voidedAt?'Anulada':balance(o)>0?'Pendiente':'Pagada',o.voidedAt?'warn':'')}</td><td>${button('Detalle',(supplier?'purchase-':'sale-')+o.id,'text')}${balance(o)>0&&allowed(supplier?'compras':'clientes','crear')?button('Abonar',(supplier?'purchase-payment-':'sale-payment-')+o.id,'text'):''}</td></tr>`))}<h3>Historial de abonos</h3>${table(['Fecha','Operación','Monto COP','Medio','Estado'],r.payments.map(p=>`<tr><td>${fmtDate(p.createdAt)}</td><td>${esc(p.parentId)}</td><td class="num">${money(p.amount)}</td><td>${esc(p.methodName||paymentNames[p.method])}</td><td>${p.voided?'Anulado':'Vigente'}</td></tr>`))}`,pButton('Exportar estado de cuenta','audit-statement-export')+(r.balance>0&&allowed(supplier?'creditos':'cartera','crear')?pButton('Abonar saldo',supplier?'supplier-pay-'+id:'customer-pay-'+id):'')+(allowed(supplier?'creditos':'cartera','editar')?pButton('Saldo inicial',supplier?'opening-supplier-'+id:'opening-customer-'+id):'')+(supplier&&r.balance>0&&allowed('creditos','eliminar')?pButton('Cancelar deuda','supplier-credit-'+id):'')+(allowed(module,'editar')?button('Editar contacto',(supplier?'supplier-edit-':'customer-edit-')+c.id):''));}
function auditServiceView(){const list=data().services.filter(o=>auditState.includeArchived?true:!o.archivedAt);return heading('Servicios y trabajos, en orden.','Catálogo de servicios y seguimiento de taller.',(allowed('servicios','crear')?pButton('Nuevo servicio','audit-service-new','primary','plus'):'')+(allowed('servicios','exportar')?pExports('servicios'):''))+`<div class="row">${pButton(auditState.includeArchived?'Ocultar archivados':'Ver archivados','audit-archived')}</div><section class="card audit-view">${table(['Servicio / Categoría','Cliente','Estado','Entrega','Precio COP',''],list.map(o=>`<tr><td><strong>${esc(o.name)}</strong><small>${esc(o.category||'Taller')} · ${o.catalog?'Catálogo':'Trabajo'}</small></td><td>${esc(o.customer||'')}</td><td>${badge(o.archivedAt?'Archivado':o.status,o.archivedAt?'warn':'')}</td><td>${fmtDate(o.dueDate)}</td><td class="num">${money(o.price)}</td><td>${allowed('servicios','editar')?pButton('Editar','audit-service-edit-'+o.id,'text'):''}${!o.archivedAt&&allowed('servicios','eliminar')?pButton('Archivar','service-delete-'+o.id,'text'):o.archivedAt&&allowed('servicios','editar')?pButton('Activar','audit-service-activate-'+o.id,'text'):''}</td></tr>`))}</section>`;}
