 const method=dialog.querySelector('#parity-method-form');if(method){const m=data().paymentMethods.find(o=>o.id===method.dataset.id);method.querySelector('.form-error').insertAdjacentHTML('beforebegin',select('Cuenta vinculada (opcional)','accountId',[['','Elegir al cobrar'],...data().accounts.filter(a=>a.active!==false).map(a=>[a.id,a.name])],m?.accountId||'')+select('Crear cuenta con este nombre','createAccount',[[0,'No'],[1,'Sí, con saldo inicial']],0)+pNum('Saldo inicial de la cuenta nueva COP','opening',0,'min="0"'));}
