function auditCalculationPreview(){const form=document.querySelector('#parity-quote-form'),target=document.querySelector('#audit-profit-preview');if(form&&target){const row=appState.cart[Number(form.dataset.index)],p=data().products.find(p=>p.id===row.productId),qty=Number(form.elements.qty.value)||0,total=Number(form.elements.lineTotal.value)||qty*(Number(form.elements.rate.value)||0)*(p.measureType==='Pesaje'?1:p.weight||1),cost=qty*p.cost;target.textContent='Proyección antes de cobrar · Costo: '+money(cost)+' · Utilidad bruta: '+money(total-cost)+' · Margen: '+(total?(total-cost)/total*100:0).toFixed(2)+' %';}}
